int main(void){UmiDataServer *server=NULL;UmiStudioServices *services;UmiStudioDatabaseExplorerCentre *c=NULL;UmiDatabaseQueryResult r;extern UmiStudioServices *umi_test_services_create(UmiDataServer *server);extern void umi_test_services_destroy(UmiStudioServices *services);assert(umi_data_server_create_memory(&server)==UMI_STATUS_OK);services=umi_test_services_create(server);assert(umi_studio_database_explorer_create(services,&c)==UMI_STATUS_OK);assert(umi_studio_database_explorer_set_write_mode(c,1)==UMI_STATUS_OK);assert(umi_studio_database_transaction_begin(c)==UMI_STATUS_OK);assert(umi_studio_database_query_execute(c,"SET theme dark",&r)==UMI_STATUS_OK);assert(umi_studio_database_transaction_commit(c)==UMI_STATUS_OK);assert(umi_studio_database_query_execute(c,"GET theme",&r)==UMI_STATUS_OK&&strcmp(r.preview,"dark")==0);umi_studio_database_explorer_destroy(c);umi_test_services_destroy(services);umi_data_server_destroy(server);return 0;}
